import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.QfQ7DfGu.js";const u=JSON.parse('{"title":"LA资源总览","description":"","frontmatter":{"title":"LA资源总览","outline":"deep"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function i(t,l,h,s,c,g){return a(),e("div",null,[...l[0]||(l[0]=[o('<h1 id="龙架构核心系统能力资源" tabindex="-1">龙架构核心系统能力资源 <a class="header-anchor" href="#龙架构核心系统能力资源" aria-label="Permalink to &quot;龙架构核心系统能力资源&quot;">​</a></h1><p class="home-overview-lede">站内主要入口汇总</p><div class="home-overview"><h2 id="教学资源" tabindex="-1"><strong>教学资源</strong> <a class="header-anchor" href="#教学资源" aria-label="Permalink to &quot;**教学资源**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/resources/courses/intro/">计算机系统</a></p><ul><li>从代码到运行，真正看懂计算机。讲清程序如何从 C 代码走到系统运行，是理解计算机系统的起点。</li></ul></li><li><p><a href="/loongarch-learning/resources/courses/arch/">组成原理/体系结构</a></p><ul><li>融合龙芯处理器研发经验，构建从指令系统到 CPU 设计的完整体系视角，迈向「能造计算机」的进阶路径。</li></ul></li><li><p><a href="/loongarch-learning/resources/courses/os/">操作系统</a></p><ul><li>汇集 MaQue、NPUcore、Ucore 等多种教学操作系统，配套教材与实验，贯通从理解原理到动手实现的学习过程。</li></ul></li><li><p><a href="/loongarch-learning/resources/courses/compiler/">编译原理</a></p><ul><li>基于龙芯等指令集实践，从前端到后端完整实现编译器，掌握真实工程中的编译技术。</li></ul></li></ul><h2 id="竞赛资源" tabindex="-1"><strong>竞赛资源</strong> <a class="header-anchor" href="#竞赛资源" aria-label="Permalink to &quot;**竞赛资源**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/competitions/os-design/kernel.html">操作系统设计赛</a></p><ul><li>历年参赛 OS 内核</li><li>历年获奖作品</li><li>历年培训报告</li><li>历年龙芯赛题</li><li>常见问题 FAQ</li></ul></li><li><p><a href="/loongarch-learning/competitions/compiler-design/training-reports.html">编译系统设计赛</a></p><ul><li>历年培训报告</li><li>历年龙芯赛题</li></ul></li></ul><h2 id="龙架构相关文档" tabindex="-1"><strong>龙架构相关文档</strong> <a class="header-anchor" href="#龙架构相关文档" aria-label="Permalink to &quot;**龙架构相关文档**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/docs-la/">官方参考手册</a></p><p>主要涉及龙架构相关开发手册：卷一基础架构（64/32 位）、LoongArch32R 精简版、ABI-2.0、工具链规约、龙架构汇编语言编程手册等。</p></li><li><p><a href="/loongarch-learning/docs-la/others-ref.html">LA32R 指令集学习指导手册</a></p><p>LA32R 指令说明与汇编编程简介。</p></li><li><p><a href="/loongarch-learning/docs-la/os-interaction.html">LoongArch 架构与 OS 交互</a></p><p>LoongArch 底层与操作系统内核交互的原理与实现要点。</p></li></ul><h2 id="龙架构基础软件" tabindex="-1"><strong>龙架构基础软件</strong> <a class="header-anchor" href="#龙架构基础软件" aria-label="Permalink to &quot;**龙架构基础软件**&quot;">​</a></h2><ul><li><p><a href="/loongarch-learning/toolchain/compiler.html">LoongArch 工具链</a></p><p>交叉编译器与相关组件：GCC 与 GLIBC、GDB、QEMU、Clang、Rust、Go、.NET 等。</p></li><li><p><a href="/loongarch-learning/docs-la/others-la64-insn.html">LoongArch 模拟器</a></p><p>LA_EMU、LoongArch QEMU、LA32R QEMU、LA32R NEMU 等。</p></li><li><p><a href="/loongarch-learning/toolchain/libc.html">LIBC 库</a></p><p>glibc、musl、newlib、piclic 等常用 C 库。</p></li><li><p><a href="/loongarch-learning/toolchain/linux-kernel.html">Linux 内核</a></p></li><li><p><a href="/loongarch-learning/toolchain/uboot.html">U-boot</a></p></li></ul><h2 id="龙架构开发平台" tabindex="-1"><strong>龙架构开发平台</strong> <a class="header-anchor" href="#龙架构开发平台" aria-label="Permalink to &quot;**龙架构开发平台**&quot;">​</a></h2><p>常用开发板与模拟器入口：</p><ul><li><a href="/loongarch-learning/platform/2k1000la.html">2k1000LA 星云板</a></li><li><a href="/loongarch-learning/platform/2k0300.html">2k0300 蜂鸟</a></li><li><a href="/loongarch-learning/platform/2k3000.html">2k3000 开发板</a></li><li><a href="/loongarch-learning/platform/qemu.html">LoongArch 模拟器</a></li></ul><h2 id="龙架构操作系统" tabindex="-1"><strong>龙架构操作系统</strong> <a class="header-anchor" href="#龙架构操作系统" aria-label="Permalink to &quot;**龙架构操作系统**&quot;">​</a></h2><ul><li><a href="/loongarch-learning/os/os-edu.html">LoongArch 教学 OS</a></li><li><a href="/loongarch-learning/os/os-kernel.html">LoongArch 开源 Kernel</a></li><li><a href="/loongarch-learning/os/release-os.html">支持龙架构的 Linux 发行版</a></li></ul><h2 id="龙架构相关的仓库" tabindex="-1"><strong>龙架构相关的仓库</strong> <a class="header-anchor" href="#龙架构相关的仓库" aria-label="Permalink to &quot;**龙架构相关的仓库**&quot;">​</a></h2><p>社区与资源链接：</p><ul><li><a href="https://github.com/LoongsonLab" target="_blank" rel="noreferrer">龙芯实验室</a></li><li><a href="https://www.loongbbs.cn/" target="_blank" rel="noreferrer">龙芯爱好者社区</a></li><li><a href="https://bbs.elecfans.com/group_1650" target="_blank" rel="noreferrer">电子发烧友龙芯版块</a></li><li><a href="http://www.loongnix.cn/zh/proj/" target="_blank" rel="noreferrer">龙芯 Loongnix 系统</a></li><li><a href="https://app.loongapps.cn" target="_blank" rel="noreferrer">龙芯应用合作社</a></li><li><a href="https://github.com/loongson" target="_blank" rel="noreferrer">龙芯开源组织（GitHub）</a></li><li><a href="https://github.com/Loongson-Cloud-Community" target="_blank" rel="noreferrer">龙芯云社区</a></li><li><a href="https://github.com/loong64" target="_blank" rel="noreferrer">loong64</a></li><li><a href="https://gitee.com/loongson" target="_blank" rel="noreferrer">龙芯开源组织（Gitee）</a></li><li><a href="https://gitee.com/openharmony-loongarch" target="_blank" rel="noreferrer">开源鸿蒙龙架构移植</a></li><li><a href="https://gitee.com/loongson-edu" target="_blank" rel="noreferrer">龙芯教育</a></li><li><a href="https://gitee.com/cn-loongson" target="_blank" rel="noreferrer">loongson 生态创新中心</a></li></ul></div><p class="home-overview-foot"><a href="./feedback/">问题反馈</a></p>',4)])])}const f=r(n,[["render",i]]);export{u as __pageData,f as default};
